BEGIN;
CREATE TABLE IF NOT EXISTS safety_cases (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, asset_id TEXT NOT NULL, jurisdiction TEXT NOT NULL, hazard_code TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN('low','medium','high','critical')), state TEXT NOT NULL CHECK(state IN('open','inspection_submitted','corrective_action','closure_review','closed','reopened')), record JSONB NOT NULL, idempotency_key TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS safety_case_events (id BIGSERIAL PRIMARY KEY, case_id BIGINT NOT NULL REFERENCES safety_cases(id), tenant_id TEXT NOT NULL, actor_id TEXT NOT NULL, event_type TEXT NOT NULL, from_state TEXT, to_state TEXT, idempotency_key TEXT, evidence_digest TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(case_id,idempotency_key));
CREATE TABLE IF NOT EXISTS safety_sync_jobs (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN('bim','gis','sensor','wearable','contractor','incident')), idempotency_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','quarantined')), payload JSONB NOT NULL, requested_by TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, failure_code TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,provider,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_safety_cases_tenant_state ON safety_cases(tenant_id,state,severity);
COMMIT;
